-- Steady-owned ingredient cost lookup. Price observations remain separate
-- from imported food-source rows and keep their own market, date, and licence.
create table public.steady_ingredient_cost_items (
  ingredient_key text primary key check (ingredient_key ~ '^[a-z][a-z0-9_]{1,63}$'),
  display_name text not null check (length(trim(display_name)) between 1 and 160),
  category text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.ingredient_cost_estimates (
  id uuid primary key default gen_random_uuid(),
  ingredient_key text not null references public.steady_ingredient_cost_items(ingredient_key) on delete restrict,
  market_country_code text not null check (market_country_code ~ '^[A-Z]{2}$'),
  currency_code text not null check (currency_code ~ '^[A-Z]{3}$'),
  reference_amount numeric(14,6) not null check (reference_amount > 0),
  reference_unit text not null check (reference_unit in ('g','ml','each')),
  estimated_cost numeric(14,6) not null check (estimated_cost >= 0),
  effective_month date not null,
  source_name text not null,
  source_item text not null,
  source_package_size text not null,
  source_pack_price numeric(14,6) not null check (source_pack_price >= 0),
  source_url text not null,
  source_licence text not null,
  source_attribution text not null,
  estimate_method text not null,
  estimate_note text not null,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  unique (ingredient_key, market_country_code, currency_code, effective_month)
);

create index ingredient_cost_estimates_active_market_idx
  on public.ingredient_cost_estimates(market_country_code, ingredient_key, effective_month desc)
  where is_active;

alter table public.steady_ingredient_cost_items enable row level security;
alter table public.ingredient_cost_estimates enable row level security;

create policy "steady cost items readable" on public.steady_ingredient_cost_items
  for select to anon, authenticated using (true);
create policy "ingredient cost estimates readable" on public.ingredient_cost_estimates
  for select to anon, authenticated using (is_active);

grant select on public.steady_ingredient_cost_items, public.ingredient_cost_estimates to anon, authenticated;
grant all on public.steady_ingredient_cost_items, public.ingredient_cost_estimates to service_role;

comment on table public.steady_ingredient_cost_items is
  'Steady-owned keys and labels for generic recipe ingredients; separate from licensed food catalogue records.';
comment on table public.ingredient_cost_estimates is
  'Approximate, dated unit-cost estimates by ingredient and market. These are not local retailer quotes; retain source attribution and price basis.';
comment on column public.ingredient_cost_estimates.estimated_cost is
  'Approximate currency amount for reference_amount and reference_unit (typically 100 g, 100 ml, or one each).';


-- Initial UK estimate set from the ONS September 2026 national average prices.
ON CONFLICT (ingredient_key) DO NOTHING;

ON CONFLICT (ingredient_key,market_country_code,currency_code,effective_month) DO NOTHING;
